-- Hospital Management System v5.0
CREATE DATABASE hospital_system;
\c hospital_system;

CREATE TABLE users(user_id SERIAL PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,full_name VARCHAR(100) NOT NULL,role VARCHAR(30) NOT NULL,department_name VARCHAR(100),is_active BOOLEAN DEFAULT true,last_login TIMESTAMP,login_attempts INTEGER DEFAULT 0,locked_until TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE patients(patient_id SERIAL PRIMARY KEY,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,date_of_birth DATE,gender VARCHAR(20),phone VARCHAR(30),address TEXT,national_id VARCHAR(50) UNIQUE,emergency_contact VARCHAR(100),emergency_phone VARCHAR(30),blood_group VARCHAR(10),allergies TEXT,chronic_conditions TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE visits(visit_id SERIAL PRIMARY KEY,patient_id INTEGER REFERENCES patients(patient_id) ON DELETE CASCADE,visit_number VARCHAR(30) UNIQUE NOT NULL,status VARCHAR(40) DEFAULT 'registered',current_department VARCHAR(50) DEFAULT 'registration',priority VARCHAR(20) DEFAULT 'normal',registration_completed BOOLEAN DEFAULT false,registration_confirmed_patient BOOLEAN DEFAULT false,registration_fee_paid BOOLEAN DEFAULT false,registration_fee_amount DECIMAL(10,2) DEFAULT 200,registration_by INTEGER REFERENCES users(user_id),registration_completed_at TIMESTAMP,triage_completed BOOLEAN DEFAULT false,triage_confirmed_patient BOOLEAN DEFAULT false,triage_category VARCHAR(30),triage_vitals_bp VARCHAR(20),triage_vitals_hr VARCHAR(20),triage_vitals_temp VARCHAR(20),triage_vitals_spo2 VARCHAR(20),triage_vitals_weight VARCHAR(20),triage_notes TEXT,triage_by INTEGER REFERENCES users(user_id),triage_completed_at TIMESTAMP,consultation_completed BOOLEAN DEFAULT false,consultation_confirmed_patient BOOLEAN DEFAULT false,consultation_notes TEXT,diagnosis TEXT,treatment_plan TEXT,prescription TEXT,consultation_by INTEGER REFERENCES users(user_id),consultation_completed_at TIMESTAMP,lab_completed BOOLEAN DEFAULT false,lab_confirmed_patient BOOLEAN DEFAULT false,lab_orders TEXT,lab_results TEXT,lab_by INTEGER REFERENCES users(user_id),lab_completed_at TIMESTAMP,radiology_completed BOOLEAN DEFAULT false,radiology_confirmed_patient BOOLEAN DEFAULT false,radiology_type VARCHAR(50),radiology_body_part VARCHAR(100),radiology_orders TEXT,radiology_findings TEXT,radiology_by INTEGER REFERENCES users(user_id),radiology_completed_at TIMESTAMP,pharmacy_completed BOOLEAN DEFAULT false,pharmacy_confirmed_patient BOOLEAN DEFAULT false,pharmacy_orders TEXT,pharmacy_dispensed TEXT,pharmacy_by INTEGER REFERENCES users(user_id),pharmacy_completed_at TIMESTAMP,ward_admitted BOOLEAN DEFAULT false,ward_confirmed_patient BOOLEAN DEFAULT false,ward_bed_number VARCHAR(20),ward_notes TEXT,ward_by INTEGER REFERENCES users(user_id),ward_admission_date TIMESTAMP,ward_discharge_date TIMESTAMP,dietary_completed BOOLEAN DEFAULT false,dietary_confirmed_patient BOOLEAN DEFAULT false,dietary_plan TEXT,dietary_restrictions TEXT,dietary_by INTEGER REFERENCES users(user_id),bloodbank_completed BOOLEAN DEFAULT false,bloodbank_confirmed_patient BOOLEAN DEFAULT false,bloodbank_request_type VARCHAR(50),bloodbank_units INTEGER,bloodbank_blood_group VARCHAR(10),bloodbank_status VARCHAR(30),bloodbank_by INTEGER REFERENCES users(user_id),socialwork_completed BOOLEAN DEFAULT false,socialwork_confirmed_patient BOOLEAN DEFAULT false,socialwork_assessment TEXT,socialwork_support_type VARCHAR(100),socialwork_notes TEXT,socialwork_by INTEGER REFERENCES users(user_id),physio_completed BOOLEAN DEFAULT false,physio_confirmed_patient BOOLEAN DEFAULT false,physio_assessment TEXT,physio_treatment_plan TEXT,physio_sessions_completed INTEGER DEFAULT 0,physio_by INTEGER REFERENCES users(user_id),isolation_completed BOOLEAN DEFAULT false,isolation_confirmed_patient BOOLEAN DEFAULT false,isolation_type VARCHAR(50),isolation_precautions TEXT,isolation_room_number VARCHAR(20),isolation_by INTEGER REFERENCES users(user_id),medrecords_completed BOOLEAN DEFAULT false,medrecords_confirmed_patient BOOLEAN DEFAULT false,medrecords_file_reference VARCHAR(100),medrecords_notes TEXT,medrecords_by INTEGER REFERENCES users(user_id),cashier_cleared BOOLEAN DEFAULT false,cashier_confirmed_patient BOOLEAN DEFAULT false,cashier_payment_method VARCHAR(30),cashier_receipt_number VARCHAR(50),cashier_by INTEGER REFERENCES users(user_id),cashier_cleared_at TIMESTAMP,referral_completed BOOLEAN DEFAULT false,referral_confirmed_patient BOOLEAN DEFAULT false,referral_hospital_name VARCHAR(200),referral_hospital_level VARCHAR(50),referral_reason TEXT,referral_by INTEGER REFERENCES users(user_id),sha_completed BOOLEAN DEFAULT false,sha_confirmed_patient BOOLEAN DEFAULT false,sha_scheme_name VARCHAR(100),sha_member_number VARCHAR(50),sha_authorization_code VARCHAR(100),sha_status VARCHAR(50),sha_notes TEXT,sha_by INTEGER REFERENCES users(user_id),morgue_completed BOOLEAN DEFAULT false,morgue_confirmed_patient BOOLEAN DEFAULT false,morgue_cause_of_death TEXT,morgue_body_released_to VARCHAR(200),morgue_notes TEXT,morgue_by INTEGER REFERENCES users(user_id),patient_cleared BOOLEAN DEFAULT false,clearance_date TIMESTAMP,clearance_by INTEGER REFERENCES users(user_id),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE visit_history(history_id SERIAL PRIMARY KEY,visit_id INTEGER REFERENCES visits(visit_id) ON DELETE CASCADE,patient_id INTEGER REFERENCES patients(patient_id) ON DELETE CASCADE,from_department VARCHAR(50),to_department VARCHAR(50),action_by INTEGER REFERENCES users(user_id),action_name VARCHAR(100),notes TEXT,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE billing_items(bill_id SERIAL PRIMARY KEY,visit_id INTEGER REFERENCES visits(visit_id) ON DELETE CASCADE,patient_id INTEGER REFERENCES patients(patient_id) ON DELETE CASCADE,item_description VARCHAR(255),department VARCHAR(50),amount DECIMAL(12,2),is_paid BOOLEAN DEFAULT false,paid_at TIMESTAMP,paid_by INTEGER REFERENCES users(user_id),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_log(log_id SERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(user_id),action VARCHAR(100),table_name VARCHAR(50),record_id INTEGER,new_values TEXT,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE inventory(item_id SERIAL PRIMARY KEY,item_name VARCHAR(200) NOT NULL,category VARCHAR(50),department VARCHAR(50),current_stock INTEGER DEFAULT 0,minimum_stock INTEGER DEFAULT 10,unit VARCHAR(30),unit_price DECIMAL(12,2),supplier VARCHAR(200),last_restocked TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE beds(bed_id SERIAL PRIMARY KEY,bed_number VARCHAR(20) UNIQUE NOT NULL,ward_type VARCHAR(50),department VARCHAR(50),is_occupied BOOLEAN DEFAULT false,current_visit_id INTEGER REFERENCES visits(visit_id),status VARCHAR(30) DEFAULT 'available',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE blood_inventory(blood_id SERIAL PRIMARY KEY,blood_group VARCHAR(10) NOT NULL,units_available INTEGER DEFAULT 0,expiry_date DATE,source VARCHAR(100),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

